/**
 * Render the single generated native TypeScript module.
 *
 * The metadata comes from the addon's `__waeTypes` export, which `#[function]`
 * and `#[object]` build in Rust. Rendering is pure: the same metadata and targets
 * always produce the same text, so CI can diff the generated file.
 *
 * Platform packages are plain `.node` carriers: they are never imported by
 * product code, and this module is the only place that maps a runtime target to
 * a package name.
 */

/** Default generated path, relative to the package that `build.types.package` names. */
export const DEFAULT_NATIVE_TYPES_OUT = 'src/native/index.ts';

/** One positional parameter of a native export. */
export type NativeParamMeta = {
    name: string;
    /** TypeScript type expression, e.g. `Array<string>`. */
    ts: string;
    optional: boolean;
};

/** One exported native function. */
export type NativeExportMeta = {
    /** Name on the addon module object. */
    js_name: string;
    params: NativeParamMeta[];
    returns: string;
    /** Legacy `fn(CallContext) -> Result<JsValue>`: the signature is not statically described. */
    untyped: boolean;
    /** `#[function(async)]`: the JS surface returns a `Promise`. */
    async: boolean;
};

/** One object interface used by an export. */
export type NativeTypeMeta = {
    name: string;
    /** Complete `export interface ...` text. */
    text: string;
};

/** One class member. */
export type NativeClassMethodMeta = {
    js_name: string;
    params: NativeParamMeta[];
    returns: string;
    kind: 'method' | 'getter';
};

/** One exported class. */
export type NativeClassMeta = {
    js_name: string;
    constructor: NativeParamMeta[];
    methods: NativeClassMethodMeta[];
};

/** `__waeTypes` payload. */
export type NativeMetadata = {
    generator: string;
    wae_version: string;
    exports: NativeExportMeta[];
    types: NativeTypeMeta[];
    /** Classes exported by the addon; absent in older metadata. */
    classes?: NativeClassMeta[];
};

/** One publishable native target, reduced to what the loader needs. */
export type NativeTypeTarget = {
    platform: string;
    arch: string;
    /** npm platform package name, e.g. `@wae/x-win32-x64`. */
    package: string;
};

/** Stable failure when metadata cannot be rendered. */
export class NativeTypegenError extends Error {
    readonly code = 'native_typegen_invalid' as const;

    constructor(message: string) {
        super(message);
        this.name = 'NativeTypegenError';
    }
}

const HEADER = `/**
 * Native addon surface.
 *
 * Generated by \`wae build types\` from the addon's \`__waeTypes\` metadata.
 * Do not edit: change the Rust \`#[function]\` / \`#[object]\` definitions and
 * rebuild instead. The step runs before \`ts\`, so the compiled surface always
 * matches the addon that was just built.
 */`;

/** Validate an `__waeTypes` payload; throws `NativeTypegenError` on any shape mismatch. */
export function parseMetadata(value: unknown): NativeMetadata {
    if (typeof value !== 'string' || value.trim() === '') {
        throw new NativeTypegenError(
            'the addon does not export `__waeTypes`; rebuild it with a wae version that emits type metadata',
        );
    }
    let parsed: unknown;
    try {
        parsed = JSON.parse(value);
    }
    catch (error) {
        throw new NativeTypegenError(`\`__waeTypes\` is not valid JSON: ${error instanceof Error ? error.message : String(error)}`);
    }
    if (parsed === null || typeof parsed !== 'object') {
        throw new NativeTypegenError('`__waeTypes` must be a JSON object');
    }
    const record = parsed as Record<string, unknown>;
    if (!Array.isArray(record.exports) || !Array.isArray(record.types)) {
        throw new NativeTypegenError('`__waeTypes` must carry `exports` and `types` arrays');
    }
    const exports = record.exports.map((item, index) => parseExport(item, index));
    const types = record.types.map((item, index) => parseType(item, index));
    const classes = Array.isArray(record.classes) ? record.classes.map((item, index) => parseClass(item, index)) : [];
    return {
        generator: typeof record.generator === 'string' ? record.generator : 'wae',
        wae_version: typeof record.wae_version === 'string' ? record.wae_version : 'unknown',
        exports,
        types,
        classes,
    };
}

function parseExport(value: unknown, index: number): NativeExportMeta {
    const where = `__waeTypes.exports[${index}]`;
    if (value === null || typeof value !== 'object') throw new NativeTypegenError(`${where} must be an object`);
    const record = value as Record<string, unknown>;
    if (typeof record.js_name !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(record.js_name)) {
        throw new NativeTypegenError(`${where}.js_name must be a JS identifier, got ${JSON.stringify(record.js_name)}`);
    }
    if (typeof record.returns !== 'string' || record.returns.trim() === '') {
        throw new NativeTypegenError(`${where}.returns must be a type expression`);
    }
    if (!Array.isArray(record.params)) throw new NativeTypegenError(`${where}.params must be an array`);
    const params = parseParams(record.params, where);
    return {
        js_name: record.js_name,
        params,
        returns: record.returns,
        untyped: record.untyped === true,
        async: record.async === true,
    };
}

function parseParams(value: unknown, where: string): NativeParamMeta[] {
    if (!Array.isArray(value)) throw new NativeTypegenError(`${where}.params must be an array`);
    return value.map((param, paramIndex) => {
        const paramWhere = `${where}.params[${paramIndex}]`;
        if (param === null || typeof param !== 'object') throw new NativeTypegenError(`${paramWhere} must be an object`);
        const entry = param as Record<string, unknown>;
        if (typeof entry.name !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(entry.name)) {
            throw new NativeTypegenError(`${paramWhere}.name must be a JS identifier`);
        }
        if (typeof entry.ts !== 'string' || entry.ts.trim() === '') {
            throw new NativeTypegenError(`${paramWhere}.ts must be a type expression`);
        }
        if (typeof entry.optional !== 'boolean') throw new NativeTypegenError(`${paramWhere}.optional must be a boolean`);
        return { name: entry.name, ts: entry.ts, optional: entry.optional };
    });
}

function parseClass(value: unknown, index: number): NativeClassMeta {
    const where = `__waeTypes.classes[${index}]`;
    if (value === null || typeof value !== 'object') throw new NativeTypegenError(`${where} must be an object`);
    const record = value as Record<string, unknown>;
    if (typeof record.js_name !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(record.js_name)) {
        throw new NativeTypegenError(`${where}.js_name must be a JS identifier, got ${JSON.stringify(record.js_name)}`);
    }
    if (!Array.isArray(record.methods)) throw new NativeTypegenError(`${where}.methods must be an array`);
    const methods = record.methods.map((method, methodIndex) => {
        const methodWhere = `${where}.methods[${methodIndex}]`;
        if (method === null || typeof method !== 'object') throw new NativeTypegenError(`${methodWhere} must be an object`);
        const entry = method as Record<string, unknown>;
        if (typeof entry.js_name !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(entry.js_name)) {
            throw new NativeTypegenError(`${methodWhere}.js_name must be a JS identifier`);
        }
        if (typeof entry.returns !== 'string' || entry.returns.trim() === '') {
            throw new NativeTypegenError(`${methodWhere}.returns must be a type expression`);
        }
        if (entry.kind !== 'method' && entry.kind !== 'getter') {
            throw new NativeTypegenError(`${methodWhere}.kind must be \`method\` or \`getter\``);
        }
        return {
            js_name: entry.js_name,
            params: parseParams(entry.params, methodWhere),
            returns: entry.returns,
            kind: entry.kind,
        } as NativeClassMethodMeta;
    });
    const constructor = parseParams(record.constructor, `${where}.constructor`);
    return { js_name: record.js_name, constructor, methods };
}

function parseType(value: unknown, index: number): NativeTypeMeta {
    const where = `__waeTypes.types[${index}]`;
    if (value === null || typeof value !== 'object') throw new NativeTypegenError(`${where} must be an object`);
    const record = value as Record<string, unknown>;
    if (typeof record.name !== 'string' || record.name.trim() === '') {
        throw new NativeTypegenError(`${where}.name must be a type name`);
    }
    if (typeof record.text !== 'string' || !record.text.trimStart().startsWith('export interface ')) {
        throw new NativeTypegenError(`${where}.text must be an \`export interface\` declaration`);
    }
    return { name: record.name, text: record.text };
}

/** Render the generated module. Pure: no filesystem access. */
export function renderNativeModule(metadata: NativeMetadata, targets: NativeTypeTarget[]): string {
    if (targets.length === 0) {
        throw new NativeTypegenError('no native targets are declared; `build.types` needs at least one');
    }
    const exports = [...metadata.exports].sort((left, right) => left.js_name.localeCompare(right.js_name));
    const types = [...metadata.types].sort((left, right) => left.name.localeCompare(right.name));
    const classes = [...(metadata.classes ?? [])].sort((left, right) => left.js_name.localeCompare(right.js_name));
    const seen = new Set<string>();
    for (const entry of exports) {
        if (seen.has(entry.js_name)) throw new NativeTypegenError(`duplicate native export \`${entry.js_name}\``);
        seen.add(entry.js_name);
    }
    const typeNames = new Set(types.map((type) => type.name));
    for (const entry of classes) {
        if (seen.has(entry.js_name)) throw new NativeTypegenError(`duplicate native export \`${entry.js_name}\``);
        if (typeNames.has(entry.js_name)) {
            throw new NativeTypegenError(`class \`${entry.js_name}\` collides with an object interface of the same name`);
        }
        seen.add(entry.js_name);
    }

    const addonMap = [...targets]
        .sort((left, right) => `${left.platform}-${left.arch}`.localeCompare(`${right.platform}-${right.arch}`))
        .map((target) => `    '${target.platform}-${target.arch}': '${target.package}',`)
        .join('\n');

    const blocks = [...types.map((type) => type.text.trimEnd()), ...classes.map(classBlock)];
    const typeBlocks = blocks.join('\n\n');

    const methodLines = [...exports.map((entry) => `    ${signature(entry)};`), ...classes.map(classMember)].join('\n');
    const forwarders = exports.map((entry) => forwarder(entry)).join('\n\n');

    return `${HEADER}

import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

/** Runtime target (\`<platform>-<arch>\`) → platform package that carries the addon. */
const ADDONS: Record<string, string> = {
${addonMap}
};

${typeBlocks}${typeBlocks === '' ? '' : '\n\n'}/** Raw surface exported by the Rust addon. */
export interface NativeModule {
${methodLines}
}

let cached: NativeModule | null = null;

/** Load the addon for the current process; throws when the platform package is missing. */
export function loadNative(): NativeModule {
    if (cached !== null) return cached;
    const key = \`\${process.platform}-\${process.arch}\`;
    const packageName = ADDONS[key];
    if (packageName === undefined) {
        throw new Error(\`no native addon is published for \\\`\${key}\\\` (supported: \${Object.keys(ADDONS).join(', ')})\`);
    }
    try {
        cached = require(packageName) as NativeModule;
        return cached;
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw new Error(\`cannot load \${packageName} for \\\`\${key}\\\`: \${message}\`);
    }
}

${forwarders}
`;
}

function signature(entry: NativeExportMeta): string {
    if (entry.untyped) return `${entry.js_name}(...args: Array<unknown>): unknown`;
    const params = entry.params.map((param) => `${param.name}${param.optional ? '?' : ''}: ${param.ts}`).join(', ');
    return `${entry.js_name}(${params}): ${returnType(entry)}`;
}

function returnType(entry: NativeExportMeta): string {
    return entry.async ? `Promise<${entry.returns}>` : entry.returns;
}

function paramsText(params: NativeParamMeta[]): string {
    return params.map((param) => `${param.name}${param.optional ? '?' : ''}: ${param.ts}`).join(', ');
}

function classBlock(entry: NativeClassMeta): string {
    const members = entry.methods
        .map((method) => (method.kind === 'getter'
            ? `    readonly ${method.js_name}: ${method.returns}`
            : `    ${method.js_name}(${paramsText(method.params)}): ${method.returns}`))
        .join('\n');
    return `export interface ${entry.js_name} {\n${members}\n}`;
}

function classMember(entry: NativeClassMeta): string {
    return `    ${entry.js_name}: { new (${paramsText(entry.constructor)}): ${entry.js_name} };`;
}

function forwarder(entry: NativeExportMeta): string {
    if (entry.untyped) {
        return `/** Exported by the Rust addon; the signature is not statically described yet. */
export function ${entry.js_name}(...args: Array<unknown>): unknown {
    return loadNative().${entry.js_name}(...args);
}`;
    }
    const params = entry.params.map((param) => `${param.name}${param.optional ? '?' : ''}: ${param.ts}`).join(', ');
    const args = entry.params.map((param) => param.name).join(', ');
    return `/** Exported by the Rust addon. */
export function ${entry.js_name}(${params}): ${returnType(entry)} {
    return loadNative().${entry.js_name}(${args});
}`;
}
